// A dialog's push button by its id (IDOK, IDCANCEL): not GetDlgItem, since some dialogs give their labels ids 1 and 2.
inline HWND dlgButton(HWND parent, int id) {
    for (HWND c = GetWindow(parent, GW_CHILD); c; c = GetWindow(c, GW_HWNDNEXT)) {
        wchar_t cls[16] = L"";
        GetClassNameW(c, cls, 16);
        if (GetDlgCtrlID(c) == id && !_wcsicmp(cls, L"Button")) return c;
    }
    return nullptr;
}
