int gUnitGraphics = 0;  // changes when syncMapUnitGraphics gives the map other unit graphics

// The unit palette in the right side bar: units in sections (Terran Ground, Zerg Air, ...), as a list
// or as a grid of command icons or unit sprites. Clicking one places it.
struct UnitPalette {
    struct Entry {
        int value = -1;  // unit type; -1 = section header
        std::wstring label;
        RECT rc{};  // content coordinates (before scrolling)
    };
    struct Bitmap {
        HBITMAP bmp = nullptr;
        int w = 0, h = 0;
    };
    HWND wnd = nullptr, search = nullptr, viewBtn = nullptr;
    HWND sectionBox = nullptr;               // units, doodads, sprites: the section the list shows ("All ..." = every one)
    std::wstring section;                    // the section shown; empty: all
    std::vector<std::wstring> sectionNames;  // what the box lists after its "All ..." item
    bool grid = false, sprites = false, large = false;
    std::vector<Entry> entries;
    std::vector<int> chosen;  // picked units; several with Ctrl+click (spray and replace use them all)
    int scroll = 0, contentH = 0, hover = -1;
    int pinned = 0;  // Doodads in a project: the pinned doodads first (entries 1..pinned, under a "Pinned" heading)
    std::map<std::tuple<int, int, int, bool>, Bitmap> bitmaps;  // (mode, value, owner, sprite)
    const void* bitmapsFor = nullptr;                      // editor the bitmaps were made with
    int bitmapsGraphics = -1;                              // ... gUnitGraphics (the unit graphics of the project's edits, or not)
    int bitmapsEra = -1, bitmapsMode = -1;                 // ... tileset, and graphics mode (0 SD, 1 HD, 2 Carbot)
    std::vector<Sprite> hdIcons;                           // HD2 (or Carbot) command icons, for bitmapsMode
    std::map<int, Sprite> hdPictures;                      // HD2 unit pictures by unit * 16 + owner
    HdTiles hdTiles;                                       // HD2 (or Carbot) megatiles, for terrain/doodad pictures
    bool hdTilesLoaded = false;
};
UnitPalette gPal;
