// --- Log (bottom of the window) -------------------------------------------------------------------------
// Everything the status bar said, euddraft's build output and startup checks, newest last. Collapsed it is
// one line: the latest message. It opens by itself on an error; click its bar (or View > Log) to toggle.
struct LogPanel {
    HWND wnd = nullptr;
    bool expanded = false, latestError = false;
    std::wstring latest;
    std::wstring latestTime;        // when (hh:mm), shown before it
    ULONGLONG latestAt = 0;         // GetTickCount64 then: an older line shows dim (not a message from now)
    int errors = 0;
    RECT toggle{};
    bool sizing = false;  // its top edge is dragged
    int grabY = 0, grabH = 0;
};
LogPanel gLog;

void uiIcon(HDC dc, RECT r, UiIcon icon, COLORREF c, int px);
// Open: the height that the user dragged, but the workspace keeps at least 200 pixels (with the top bar, the tabs and
// the status bar above and below it).
int logPanelHeight() {
    if (!gLog.wnd) return 0;
    if (!gLog.expanded) return scale(24);
    RECT rc{};
    GetClientRect(app.main, &rc);
    const int room = int(rc.bottom) - scale(40) - tabStripHeight() - scale(24) - scale(200);  // top bar, tabs, status bar, workspace
    return std::clamp(scale(gDock.logH), scale(80), std::max(scale(80), room));
}

void logSetExpanded(bool on) {
    if (gLog.expanded == on || !gLog.wnd) return;
    gLog.expanded = on;
    ShowWindow(gBuildLogText, on ? SW_SHOW : SW_HIDE);
    shellRelayout();
    if (on) {  // the newest lines in view
        const int end = GetWindowTextLengthW(gBuildLogText);
        SendMessageW(gBuildLogText, EM_SETSEL, end, end);
        SendMessageW(gBuildLogText, EM_SCROLLCARET, 0, 0);
    }
}

void logDimLater();  // (LogView: the latest line turns dim later)

void logLine(const std::wstring& line, bool error) {
    if (!line.empty()) crash::remember(line);
    if (line.empty() || !gBuildLogText) return;
    if (!error && line == gLog.latest) return;  // the same message again
    const int len = GetWindowTextLengthW(gBuildLogText);
    if (len > 400000) {  // keep the newest half
        SendMessageW(gBuildLogText, EM_SETSEL, 0, len / 2);
        SendMessageW(gBuildLogText, EM_REPLACESEL, FALSE, LPARAM(L"(older lines dropped)\r\n"));
    }
    SYSTEMTIME t;
    GetLocalTime(&t);
    wchar_t stamp[16];
    std::swprintf(stamp, 16, L"%02d:%02d:%02d  ", t.wHour, t.wMinute, t.wSecond);
    const int end = GetWindowTextLengthW(gBuildLogText);
    SendMessageW(gBuildLogText, EM_SETSEL, end, end);
    SendMessageW(gBuildLogText, EM_REPLACESEL, FALSE, LPARAM((stamp + std::wstring(error ? L"ERROR  " : L"") + line + L"\r\n").c_str()));
    gLog.latest = line, gLog.latestError = error;
    wchar_t hm[8];
    std::swprintf(hm, 8, L"%02d:%02d", t.wHour, t.wMinute);
    gLog.latestTime = hm, gLog.latestAt = GetTickCount64();
    if (gLog.wnd) logDimLater();  // then it turns dim
    if (error) ++gLog.errors, logSetExpanded(true);
    if (gLog.wnd) InvalidateRect(gLog.wnd, nullptr, FALSE);
}

void buildLogAppend(const std::wstring& line) {
    const bool error = line.find(L"[Error]") != std::wstring::npos || line.find(L"Traceback") != std::wstring::npos ||
                       line.find(L"Error:") != std::wstring::npos;
    logLine(line, error);
}

// A build starts: a separator line; the log stays as it is (it opens by itself if the build fails).
