void addProjectScript() {
    EudProject* pr = activeProject();
    if (!pr) return;
    platform::FileDialog d;
    d.owner = app.main;
    d.filters = {{"epScript (*.eps)", "*.eps"}, {"eudplib Python (*.py)", "*.py"}};
    d.fileName = L"new.eps";
    d.initialDir = pr->folder() / "scripts";
    d.title = narrow(L"Add a script: select one, or type the name of a new one");
    d.defaultExtension = "eps";
    d.pathMustExist = true;
    const auto picked = platform::saveFileDialog(d);
    if (!picked) return;
    const fs::path file = *picked;
    std::error_code ec;
    if (!fs::exists(file, ec)) {
        std::ofstream f(file, std::ios::binary);
        f << "// " << file.filename().string() << "\n\nfunction onPluginStart() {\n}\n";
        f.close();
        if (!f) return void(themedMessageBox(app.main, (L"Could not write " + file.wstring()).c_str(), L"Add a script", MB_ICONERROR));
    }
    fs::path rel = fs::relative(file, pr->folder(), ec);
    if (ec || rel.empty() || rel.native().rfind(L"..", 0) == 0) rel = file;  // outside the folder: keep the full path
    pr->addScript(rel.generic_string());
    std::string err;
    if (!pr->save(err)) themedMessageBox(app.main, widen(err).c_str(), L"Could not save the project", MB_ICONERROR);
    else setMessage(L"Added " + rel.wstring() + L" to the project");
    triggersRefresh(rel.generic_string());
}


// New map of a tileset, filled with one terrain.
void newMap(uint16_t width, uint16_t height, uint16_t era, uint16_t terrain) {
    auto ed = std::make_unique<Editor>(app.data);
    std::string err;
    SetCursor(LoadCursor(nullptr, IDC_WAIT));
    if (!ed->newMap(width, height, era, terrain, err)) {
        themedMessageBox(app.main, widen(err).c_str(), L"Could not create the map", MB_ICONERROR);
        return;
    }
    addDocument(std::move(ed));
    const IsomTerrainTable* table = IsomTerrainTable::forEra(era);
    setMessage(L"Created a new " + std::wstring(kTilesetNames[era & 7]) + L" map (" + std::to_wstring(width) + L"x" + std::to_wstring(height) + L", " +
               widen(table ? table->terrainName(terrain) : "") + L")");
}

// The default new map: badlands dirt, 128x128 (startup, the + tab button).
void newMap() { newMap(128, 128, 0, 1); }

// --- The unsaved project ---------------------------------------------------------------------------------------
// StarDraft starts with a project that is not saved yet: a 128 x 128 badlands map in a project folder under
// %LOCALAPPDATA%\StarDraft\Unsaved\<process>-<time>\Untitled, so every workspace works from the start. Save asks
// where the project goes; closing it without saving deletes the folder.
fs::path unsavedRoot() {
    wchar_t* local = nullptr;
    fs::path p;
    if (SUCCEEDED(SHGetKnownFolderPath(FOLDERID_LocalAppData, 0, nullptr, &local))) p = fs::path(local) / "StarDraft" / "Unsaved";
    CoTaskMemFree(local);
    return p;
}
// The folders of unsaved projects whose StarDraft is no longer running (a crash, an older start).
void cleanUnsavedProjects() {
    std::error_code ec;
    for (const auto& e : fs::directory_iterator(unsavedRoot(), ec)) {
        const std::string name = e.path().filename().string();
        const DWORD pid = DWORD(std::strtoul(name.c_str(), nullptr, 10));
        if (pid == GetCurrentProcessId()) continue;
        if (HANDLE h = OpenProcess(SYNCHRONIZE, FALSE, pid)) {  // still running (another StarDraft)
            const bool alive = WaitForSingleObject(h, 0) == WAIT_TIMEOUT;
            CloseHandle(h);
            if (alive) continue;
        }
        fs::remove_all(e.path(), ec);
    }
}
void newUntitledProject() {
    newMap();
    if (!app.ed || gActive < 0) return;
    static bool cleaned = false;
    if (!cleaned) cleaned = true, cleanUnsavedProjects();
    std::error_code ec;
    const fs::path parent = unsavedRoot() / (std::to_string(GetCurrentProcessId()) + "-" + std::to_string(GetTickCount64()));
    fs::create_directories(parent, ec);
    auto pr = std::make_shared<EudProject>();
    std::string err;
    if (!EudProject::create(parent, "Untitled", {}, *pr, err) || !app.ed->save(pr->folder() / "Untitled.scx", err) || !pr->open(pr->file(), err)) {
        logLine(L"Cannot make the new project: " + widen(err), true);  // the map stays: a plain map
        return;
    }
    gDocs[size_t(gActive)].project = pr;
    updateTitle();
    if (gWsBar) InvalidateRect(gWsBar, nullptr, FALSE);
    if (app.tabs) InvalidateRect(app.tabs, nullptr, FALSE);
}
bool saveUnsavedProjectTo(const fs::path& chosen);
// Save for an unsaved project: where it goes (a folder of its name is made there), then everything moves there and
// the tab goes on as that project.
bool saveUnsavedProject() {
    EudProject* pr = activeProject();
    if (!pr || !app.ed) return false;
    const fs::path initial = defaultProjectsFolder();
    platform::FileDialog d;
    d.owner = app.main;
    d.filters = {{"StarDraft 2 project (*.stardraft)", "*.stardraft"}};
    d.defaultExtension = "stardraft";
    d.fileName = L"Untitled";
    d.initialDir = initial;
    d.title = narrow(L"Save the project (StarDraft 2 makes a folder with its name here)");
    d.pathMustExist = d.noReadOnly = true;
    std::error_code ec;
    fs::create_directories(initial, ec);
    const auto picked = platform::saveFileDialog(d);
    if (!picked) return false;
    return saveUnsavedProjectTo(picked->wstring());
}
// The same, to `chosen` (<folder>\<name>.stardraft: the project goes to <folder>\<name>\).
bool saveUnsavedProjectTo(const fs::path& chosen) {
    EudProject* pr = activeProject();
    if (!pr || !app.ed) return false;
    std::error_code ec;
    const std::string name = chosen.stem().string();
    const fs::path dest = chosen.parent_path() / chosen.stem();
    if (name.empty() || name.find_first_of("\\/:*?\"<>|") != std::string::npos) return themedMessageBox(app.main, L"The name cannot hold \\ / : * ? \" < > |", L"Save project", MB_ICONWARNING), false;
    if (fs::exists(dest, ec) && !fs::is_empty(dest, ec)) {
        themedMessageBox(app.main, (dest.wstring() + L" is there already and is not empty.").c_str(), L"Save project", MB_ICONWARNING);
        return false;
    }
    std::string err;
    if (!app.ed->save(pr->inputMap(), err)) return themedMessageBox(app.main, widen(err).c_str(), L"Could not save the map", MB_ICONERROR), false;
    // Everything in the folder, with the project's own files named after it.
    const fs::path from = pr->folder();
    fs::create_directories(dest, ec);
    for (auto it = fs::recursive_directory_iterator(from, ec); it != fs::recursive_directory_iterator(); it.increment(ec)) {
        const fs::path rel = fs::relative(it->path(), from, ec);
        const std::string r = rel.generic_string();
        if (r == "Untitled_EUD.scx" || r == "Untitled.eds") continue;  // Build makes them again
        fs::path to = dest / rel;
        if (r == "Untitled.scx") to = dest / (name + ".scx");
        if (it->is_directory(ec)) {
            fs::create_directories(to, ec);
            continue;
        }
        if (r == EudProject::kFileName) {  // its name, map and output by the new name
            std::ifstream in(it->path(), std::ios::binary);
            std::string text((std::istreambuf_iterator<char>(in)), {});
            for (const auto& [a, b] : {std::pair<std::string, std::string>{"Untitled_EUD.scx", name + "_EUD.scx"}, {"Untitled.scx", name + ".scx"},
                                       {"name: Untitled", "name: " + name}, {"Untitled.eds", name + ".eds"}})
                for (size_t p = text.find(a); p != std::string::npos; p = text.find(a, p + b.size())) text.replace(p, a.size(), b);
            std::ofstream out(dest / EudProject::kFileName, std::ios::binary);
            out << text;
            out.close();
            if (!out) return themedMessageBox(app.main, (L"Could not write " + (dest / EudProject::kFileName).wstring()).c_str(), L"Save project", MB_ICONERROR), false;
            continue;
        }
        fs::copy_file(it->path(), to, fs::copy_options::overwrite_existing, ec);
        if (ec) return themedMessageBox(app.main, (L"Could not copy " + it->path().wstring() + L": " + widen(ec.message())).c_str(), L"Save project", MB_ICONERROR), false;
    }
    // The tab goes on as the saved project (the same project object: the workspaces keep it).
    const fs::path oldParent = from.parent_path();
    if (!pr->open(dest / EudProject::kFileName, err) || !app.ed->save(pr->inputMap(), err)) return themedMessageBox(app.main, widen(err).c_str(), L"Save project", MB_ICONERROR), false;
    fs::remove_all(oldParent, ec);
    addRecent(gRecentProjects, pr->folder());
    rememberProjectsFolder(pr->folder());
    updateTitle();
    setWorkspace(gWorkspace);  // the workspaces read the project from its new folder
    if (app.tabs) InvalidateRect(app.tabs, nullptr, FALSE);
    setMessage(L"Saved the project to " + dest.wstring());
    return true;
}

bool createProject(const fs::path& parent, const std::string& name, bool fromOpenMap, std::string& err, const fs::path& outputFile);

bool saveUnsavedProject();
bool isUnsavedProject(const EudProject* pr);
bool unsavedProjectTouched(const EudProject& pr);
bool saveMap(bool as) {
    if (!app.ed || !app.ed->isOpen()) return false;
    mapPageFlush();  // a text being typed on a map page is saved too
    if (isUnsavedProject(activeProject())) return saveUnsavedProject();
    std::wstring path = app.ed->path().wstring();
    bool programFiles = path.find(L"Program Files") != std::wstring::npos;
    if (as || programFiles || path.empty()) {
        path = fileDialog(true);
        if (path.empty()) return false;
    }
    std::string err;
    if (!saveMapFile(fs::path(path), err)) {
        themedMessageBox(app.main, widen(err).c_str(), L"Could not save the map", MB_ICONERROR);
        return false;
    }
    return true;
}


void enableDarkModeForApp();
void darkControl(HWND w, const wchar_t* theme);
extern std::vector<std::pair<HWND, std::wstring>> gThemedControls;

// File > Options > Appearance (theme and accent color): every token, brush and Windows theme for the choice, then every window painted
// again. Kept in the settings (not by test runs).
void themeRefreshControls();  // the controls that keep colors of their own (defined with them)
void setMenuIcons(HMENU bar);
void applyTheme(bool light, int accent) {
    setThemeColors(light, accent);
    syncKitTheme();
    const HBRUSH oldBg = app.bgBrush, oldCtl = app.ctlBrush;
    app.bgBrush = CreateSolidBrush(kBg), app.ctlBrush = CreateSolidBrush(kCtl);
    enableDarkModeForApp();
    // The window classes that paint their ground with the old brushes take the new ones.
    std::vector<HWND> all;
    EnumThreadWindows(
        GetCurrentThreadId(),
        [](HWND w, LPARAM lp) -> BOOL {
            auto& v = *reinterpret_cast<std::vector<HWND>*>(lp);
            v.push_back(w);
            EnumChildWindows(
                w,
                [](HWND c, LPARAM lp2) -> BOOL {
                    reinterpret_cast<std::vector<HWND>*>(lp2)->push_back(c);
                    return TRUE;
                },
                lp);
            return TRUE;
        },
        LPARAM(&all));
    for (HWND w : all) {
        const auto bg = HBRUSH(GetClassLongPtrW(w, GCLP_HBRBACKGROUND));
        if (bg == oldBg) SetClassLongPtrW(w, GCLP_HBRBACKGROUND, LONG_PTR(app.bgBrush));
        else if (bg == oldCtl) SetClassLongPtrW(w, GCLP_HBRBACKGROUND, LONG_PTR(app.ctlBrush));
    }
    DeleteObject(oldBg), DeleteObject(oldCtl);
    if (app.main) setMenuIcons(GetMenu(app.main));  // the icons in the new text color
    std::erase_if(gThemedControls, [](const auto& t) { return !IsWindow(t.first); });
    for (const auto& [w, name] : std::vector(gThemedControls)) darkControl(w, name.c_str());
    for (HWND w : all)
        if ((GetWindowLongW(w, GWL_STYLE) & WS_CAPTION) == WS_CAPTION) {  // every window with a title bar (owned ones too: Block help; not pop-ups)
            BOOL dark = !gLightTheme;
            DwmSetWindowAttribute(w, 20, &dark, sizeof dark), titleColors(w);
        }
    restyleTips();  // the tooltips' border in the new theme
    for (HWND w : all)
        if (!GetParent(w)) RedrawWindow(w, nullptr, nullptr, RDW_INVALIDATE | RDW_ERASE | RDW_FRAME | RDW_ALLCHILDREN | RDW_UPDATENOW);
    themeRefreshControls();
    if (app.main) DrawMenuBar(app.main);
    app.dirty = true;
    if (!gSelfTest && !gBackground) {
        prefs::setNumber(L"LightTheme", light ? 1 : 0);
        prefs::setNumber(L"Accent", gAccentIndex);
    }
    setMessage(std::wstring(light ? L"Light" : L"Dark") + L" theme, accent color " + theme::kAccents[gAccentIndex].name);
}
