                            shot = dir / "111_popout_variable_size.png";
                            SendMessageW(gTE.pane, WM_LBUTTONDOWN, MK_LBUTTON, MAKELPARAM((vh.r.left + vh.r.right) / 2, (vh.r.top + vh.r.bottom) / 2));
