                    if (at != std::wstring::npos) {
                        const RECT pr = richRunRect(gValuePop->edit, {LONG(at), LONG(at + 13)});
                        richEditChip(LONG(at), {(pr.left + pr.right) / 2, (pr.top + pr.bottom) / 2});
                    }
                    gListPickHook = nullptr;
                    log << "after changing the chip's unit: \"" << richRawText(gValuePop->edit) << "\" " << narrow(windowText(gValuePop->edit)) << "\n";
                    // @, then a value from the game: Kills.
